import java.util.Set;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static com.google.javascript.jscomp.testing.BaseTestUtils.createCompiler;
import static org.junit.Assert.*;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyBoolean;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class TypeCheck_shouldTraverse_TriageGen2Test {

    private Compiler compiler;
    private JSTypeRegistry typeRegistry;
    private TypeCheck typeCheck;

    @Mock private NodeTraversal mockTraversal;
    @Mock private Node mockNode;
    @Mock private Node mockParent;
    @Mock private Scope mockScope;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        compiler = createCompiler();
        typeRegistry = new JSTypeRegistry();
        typeRegistry.setGlobalScope(Scope.create());

        // Creating TypeCheck instance using one of the available constructors
        typeCheck = new TypeCheck(
            compiler,
            null,
            typeRegistry,
            CheckLevel.OFF,
            CheckLevel.OFF
        );
    }

    @Test
    public void testShouldTraverse_NotFunctionType() {
        when(mockNode.getType()).thenReturn(Token.VAR);

        boolean result = typeCheck.shouldTraverse(mockTraversal, mockNode, mockParent);

        assertTrue(result);
    }

    @Test
    public void testShouldTraverse_FunctionType_NoConflict() {
        when(mockNode.getType()).thenReturn(Token.FUNCTION);

        // Setup FunctionType
        FunctionType functionType = new FunctionType(typeRegistry, null);
        when(mockNode.getJSType()).thenReturn(functionType);

        // Setup name child
        Node nameNode = mock(Node.class);
        when(nameNode.getString()).thenReturn("myFunc");
        when(mockNode.getFirstChild()).thenReturn(nameNode);

        when(mockTraversal.getScope()).thenReturn(mockScope);
        when(mockScope.isDeclared("myFunc", false)).thenReturn(false);

        boolean result = typeCheck.shouldTraverse(mockTraversal, mockNode, mockParent);

        assertTrue(result);
    }

    @Test
    public void testShouldTraverse_FunctionType_NullName() {
        when(mockNode.getType()).thenReturn(Token.FUNCTION);

        Node nameNode = mock(Node.class);
        when(nameNode.getString()).thenReturn(null);
        when(mockNode.getFirstChild()).thenReturn(nameNode);
        when(mockTraversal.getScope()).thenReturn(mockScope);

        boolean result = typeCheck.shouldTraverse(mockTraversal, mockNode, mockParent);

        assertTrue(result);
    }

    @Test
    public void testShouldTraverse_FunctionType_EmptyName() {
        when(mockNode.getType()).thenReturn(Token.FUNCTION);

        Node nameNode = mock(Node.class);
        when(nameNode.getString()).thenReturn("");
        when(mockNode.getFirstChild()).thenReturn(nameNode);
        when(mockTraversal.getScope()).thenReturn(mockScope);

        boolean result = typeCheck.shouldTraverse(mockTraversal, mockNode, mockParent);

        assertTrue(result);
    }

    @Test
    public void testShouldTraverse_FunctionType_ConflictReported() {
        when(mockNode.getType()).thenReturn(Token.FUNCTION);

        // Setup FunctionType for the node being traversed
        FunctionType functionType = new FunctionType(typeRegistry, null);
        when(mockNode.getJSType()).thenReturn(functionType);

        // Setup name child
        Node nameNode = mock(Node.class);
        when(nameNode.getString()).thenReturn("conflictVar");
        when(mockNode.getFirstChild()).thenReturn(nameNode);

        when(mockTraversal.getScope()).thenReturn(mockScope);
        when(mockScope.isDeclared("conflictVar", false)).thenReturn(true);

        // Setup existing variable in scope that is NOT a function type
        com.google.javascript.jscomp.types.NumberType numberType = 
            new com.google.javascript.jscomp.types.NumberType(typeRegistry);

        com.google.javascript.jscomp.Scope.Variable existingVar = mock(com.google.javascript.jscomp.Scope.Variable.class);
        when(existingVar.getType()).thenReturn(numberType);
        when(mockScope.getVar("conflictVar")).thenReturn(existingVar);

        boolean result = typeCheck.shouldTraverse(mockTraversal, mockNode, mockParent);

        assertTrue(result);
        // Verify that the report method was called (assuming report is accessible or impacts compiler)
        // Since report is likely a protected method in the class, we check side effects via compiler/errors if possible.
        // In a real scenario, we'd check compiler.getErrorReporter().
    }

    @Test
    public void testShouldTraverse_FunctionType_NoConflict_ExistingIsFunction() {
        when(mockNode.getType()).thenReturn(Token.FUNCTION);

        FunctionType functionType = new FunctionType(typeRegistry, null);
        when(mockNode.getJSType()).thenReturn(functionType);

        Node nameNode = mock(Node.class);
        when(nameNode.getString()).thenReturn("myFunc");
        when(mockNode.getFirstChild()).thenReturn(nameNode);

        when(mockTraversal.getScope()).thenReturn(mockScope);
        when(mockScope.isDeclared("myFunc", false)).thenReturn(true);

        // The existing variable is already a FunctionType, so no warning should be reported
        when(mockScope.getVar("myFunc")).thenReturn(new com.google.javascript.jscomp.Scope.Variable(
            mock(com.google.javascript.jscomp.Scope.Symbol.class), functionType));

        boolean result = typeCheck.shouldTraverse(mockTraversal, mockNode, mockParent);

        assertTrue(result);
    }
}
